import sys
input = sys.stdin.read

MOD = 10**9 + 7

def solve(n, T, songs):
    dp = [{} for _ in range(T + 1)]
    dp[0][0] = 1

    for time in range(T):
        for last_genre, count in dp[time].items():
            for i in range(n):
                song_time, song_genre = songs[i]
                if song_genre != last_genre:
                    new_time = time + song_time
                    if new_time <= T:
                        if song_genre in dp[new_time]:
                            dp[new_time][song_genre] += count
                        else:
                            dp[new_time][song_genre] = count
                        dp[new_time][song_genre] %= MOD
                        if i == n - 1 and new_time == T and len(set(song[1] for song in songs)) == 3:
                            dp[new_time][song_genre] += count
                            dp[new_time][song_genre] %= MOD

    result = 0
    for count in dp[T].values():
        result = (result + count) % MOD

    return result

def main():
    data = input().split()
    n = int(data[0])
    T = int(data[1])
    songs = []
    index = 2
    for _ in range(n):
        t_i = int(data[index])
        g_i = int(data[index + 1])
        songs.append((t_i, g_i))
        index += 2

    result = solve(n, T, songs)
    print(result)

